import React, { useState, useRef } from 'react';
import { GoogleMap, LoadScript, Marker, Autocomplete } from '@react-google-maps/api';

const MapComponent = ({ onLocationSelect }) => {
  const [selectedLocation, setSelectedLocation] = useState(null);
  const [address, setAddress] = useState('');
  const autocompleteRef = useRef(null); // для хранения ссылки на Autocomplete

  const mapStyles = {
    height: "400px",
    width: "100%"
  };

  const defaultCenter = {
    lat: 41.2995, // Центральные координаты Ташкента
    lng: 69.2401
  };

  const handleMapClick = (event) => {
    const lat = event.latLng.lat();
    const lng = event.latLng.lng();
    setSelectedLocation({ lat, lng });
    onLocationSelect({ lat, lng });
  };

  const handlePlaceSelected = () => {
    const place = autocompleteRef.current.getPlace();
    if (place.geometry) {
      const lat = place.geometry.location.lat();
      const lng = place.geometry.location.lng();
      setSelectedLocation({ lat, lng });
      onLocationSelect({ lat, lng });
      setAddress(place.formatted_address);
    }
  };

  return (
    <LoadScript googleMapsApiKey="AIzaSyDqAZMwSS6oDk-9FHLeTwtP_tL_3Iqq_aE" libraries={['places']}>
      <div>
        <Autocomplete
          onLoad={(autocomplete) => (autocompleteRef.current = autocomplete)}
          onPlaceChanged={handlePlaceSelected}
        >
          <input
            type="text"
            placeholder="Введите место"
            style={{ width: '100%', padding: '10px', marginBottom: '10px' }}
          />
        </Autocomplete>

        <GoogleMap
          mapContainerStyle={mapStyles}
          zoom={13}
          center={selectedLocation || defaultCenter}
          onClick={handleMapClick}
        >
          {selectedLocation && <Marker position={selectedLocation} />}
        </GoogleMap>

        {address && <p>Адрес: {address}</p>}
      </div>
    </LoadScript>
  );
};

export default MapComponent;
